package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class ItemChecks {
    private GameWorld world(){GameWorld w=new GameWorld();w.enemies.clear();w.setDropSeed(0);return w;}
    private void tick(GameWorld w,int n){for(int i=0;i<n;i++)w.step(1f/60,0,false,false);}
    private GameWorld.Enemy target(GameWorld w,float x,float y){GameWorld.Enemy e=new GameWorld.Enemy(x,y,true);e.hp=e.maxHp=300;e.timer=100;w.enemies.add(e);return e;}
    @Test public void weightedCandyIsMostCommon(){int[] counts=new int[GameWorld.Item.values().length];for(int n=0;n<100;n++)counts[GameWorld.rollItem(n).ordinal()]++;assertEquals(40,counts[0]);for(int n=1;n<counts.length;n++)assertTrue(counts[0]>counts[n]);}
    @Test public void candyLevelsUnlocksAndHeals(){GameWorld w=world();w.hp=2;w.xp=30;w.collectItem(GameWorld.Item.CANDY);assertEquals(2,w.level);assertEquals(0,w.xp);assertEquals(4,w.hp);assertTrue(w.skillUnlocked(1));assertEquals(0,w.itemCount(GameWorld.Item.CANDY));}
    @Test public void dropsLandAndAutoCollectOnlyNearby(){GameWorld w=world();GameWorld.Drop drop=new GameWorld.Drop(GameWorld.Item.BERRY,300,145);w.drops.add(drop);w.hp=2;tick(w,90);assertEquals(1,w.drops.size());assertEquals(124,drop.y,.1);w.x=280;tick(w,2);assertTrue(w.drops.isEmpty());assertEquals(4,w.hp);}
    @Test public void multiLensEchoDoesNotRepeatForever(){GameWorld w=world();w.collectItem(GameWorld.Item.MULTI);GameWorld.Enemy e=target(w,250,112);w.trySkill(0);tick(w,45);assertEquals(252,e.hp);tick(w,30);assertTrue(e.hp>=249);assertEquals(0,w.kills);}
    @Test public void charcoalAndFangBoostOnlyMatchingElement(){GameWorld w=world();w.collectItem(GameWorld.Item.CHARCOAL);GameWorld.Enemy e=target(w,250,112);w.trySkill(0);tick(w,35);assertEquals(262,e.hp);w=world();w.addExperience(100);w.collectItem(GameWorld.Item.FANG);e=target(w,250,112);w.trySkill(2);tick(w,35);assertEquals(263,e.hp);}
    @Test public void wideLensCurvesTowardRaisedEnemy(){GameWorld w=world();w.collectItem(GameWorld.Item.WIDE);target(w,320,205);w.trySkill(0);tick(w,25);assertFalse(w.skillShots.isEmpty());assertTrue(w.skillShots.get(0).vy>0);assertTrue(w.skillShots.get(0).y>150);}
    @Test public void sashConsumedOnceAndLeavesHalfHeart(){GameWorld w=world();w.collectItem(GameWorld.Item.SASH);w.damage(99,200);assertEquals(1,w.hp);assertEquals(0,w.itemCount(GameWorld.Item.SASH));w.invulnerable=0;w.damage(99,200);assertEquals(0,w.hp);}
    @Test public void leftoversPauseAndUnlimitedStacks(){GameWorld w=world();w.collectItem(GameWorld.Item.LEFTOVERS);w.hp=2;w.paused=true;tick(w,800);assertEquals(2,w.hp);w.paused=false;tick(w,730);assertEquals(3,w.hp);for(int i=0;i<5;i++)w.collectItem(GameWorld.Item.CHARCOAL);assertEquals(5,w.itemCount(GameWorld.Item.CHARCOAL));}
    @Test public void inventoryCarriesAndRetryRestoresEntry(){GameWorld w=world();w.collectItem(GameWorld.Item.SASH);w.stageComplete=true;assertTrue(w.advanceStage());assertEquals(1,w.itemCount(GameWorld.Item.SASH));w.collectItem(GameWorld.Item.MULTI);w.invulnerable=0;w.damage(99,200);w.invulnerable=0;w.damage(99,200);assertTrue(w.retryStage());assertEquals(1,w.itemCount(GameWorld.Item.SASH));assertEquals(0,w.itemCount(GameWorld.Item.MULTI));w.restart();assertEquals(0,w.itemCount(GameWorld.Item.SASH));}
    @Test public void killDropsAndRewardsExactlyOnce(){GameWorld w=world();GameWorld.Enemy e=target(w,250,112);e.hp=1;w.trySkill(0);tick(w,40);assertEquals(1,w.kills);assertEquals(25,w.xp);assertEquals(1,w.drops.size());tick(w,40);assertEquals(1,w.kills);assertEquals(1,w.drops.size());}
    @Test public void everyHeldToolCanStackPastOldCaps(){GameWorld w=world();for(GameWorld.Item item:GameWorld.Item.values())if(item.held()){for(int n=0;n<12;n++)w.collectItem(item);assertEquals(12,w.itemCount(item));assertFalse(w.itemSummary(item).isEmpty());}}
    @Test public void newDamageToolsAffectMatchingAttacks(){GameWorld w=world();w.collectItem(GameWorld.Item.MUSCLE);w.collectItem(GameWorld.Item.SCARF);assertEquals(32,w.attackDamage());w.collectItem(GameWorld.Item.GLASSES);GameWorld.Enemy e=target(w,250,112);w.trySkill(0);tick(w,35);assertEquals(263,e.hp);}
    @Test public void quickClawAndLuckyEggStack(){GameWorld w=world();w.collectItem(GameWorld.Item.CLAW);w.collectItem(GameWorld.Item.CLAW);assertEquals(1/1.24f,w.cooldownScale(),.0001f);w.collectItem(GameWorld.Item.EGG);w.collectItem(GameWorld.Item.EGG);GameWorld.Enemy e=target(w,250,112);e.hp=1;w.trySkill(0);assertTrue(w.skillCooldowns[0]<1.4f);tick(w,35);assertEquals(38,w.xp);}
    @Test public void shellBellHealsOnDirectHitsAndMultiStacks(){GameWorld w=world();for(int i=0;i<6;i++)w.collectItem(GameWorld.Item.SHELL);w.collectItem(GameWorld.Item.MULTI);w.collectItem(GameWorld.Item.MULTI);w.hp=2;GameWorld.Enemy e=target(w,250,112);w.trySkill(0);tick(w,45);assertEquals(236,e.hp);assertEquals(3,w.hp);}
    @Test public void expertBeltAndScopeApplyToDirectDamage(){GameWorld w=world();GameWorld.Enemy e=target(w,250,112);e.boss=true;w.bossActive=true;w.boss=e;w.collectItem(GameWorld.Item.BELT);for(int i=0;i<100;i++)w.collectItem(GameWorld.Item.SCOPE);w.trySkill(0);tick(w,35);assertEquals(243,e.hp);}
    @Test public void ownedIconsUseLeftCornerAndHoverFollowsInventory(){GameWorld w=world();assertNull(ItemHud.at(w,30,660));w.collectItem(GameWorld.Item.FANG);assertEquals(GameWorld.Item.FANG,ItemHud.at(w,30,660));w.collectItem(GameWorld.Item.MULTI);assertEquals(GameWorld.Item.MULTI,ItemHud.at(w,30,660));assertEquals(GameWorld.Item.FANG,ItemHud.at(w,95,660));assertNull(ItemHud.at(w,500,660));for(GameWorld.Item i:GameWorld.Item.values())if(i.held())w.collectItem(i);assertEquals(GameWorld.Item.BELT,ItemHud.at(w,ItemHud.x(13)+10,ItemHud.y(13)+10));}}